        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        #5 reset = 0; // Release reset

