        #10;
        if (q !== 16'b0000000000000000 || ena !== 4'b0000) begin
            $display("Error: Initial state mismatch.");
            errors = errors + 1;
        end

        // Simulate clock and check outputs
        repeat (20) begin
            #5 clk = ~clk; // Toggle clock
            if (clk) begin // Check on rising edge
                // Check expected values
                if (q !== {dut.thousands, dut.hundreds, dut.tens, dut.ones}) begin
                    $display("Error: Output q mismatch at time %0t. Expected: %b, Got: %b", $time, {dut.thousands, dut.hundreds, dut.tens, dut.ones}, q);
                    errors = errors + 1;
                end
                // Check enable signals
                if (ena[0] !== (dut.ones == 4'b1001)) begin
